        const remove = await window.gConfirm('Do you want to delete this bookmark?', 'Delete bookmark');
        if (remove) {
            const index = this.bookmarks.indexOf(bookmark);
            if (index >= 0) {
                this.bookmarks.splice(index, 1);
            }
            this.saveBookmarks();
            super.render();
            super.girafeTranslate();
        }
