    if (inputStr.startsWith('http')) {
        return `<a href="${inputStr}" target="_blank" rel="noreferrer">${inputStr}</a>`;
    }
    // Create an emial link if has email form
    if (isValidEmail(inputStr)) {
        return `<a href="mailto:${inputStr}">${inputStr}</a>`;
    }
